import json

with open('/app/resources/treasury_bulletin_1963_12.json', 'r') as f:
    data = json.load(f)

# Look for keys that might contain exchange rate info
def find_keys(d, target):
    if isinstance(d, dict):
        for k, v in d.items():
            if target.lower() in str(k).lower():
                print(f"Found key: {k}")
            find_keys(v, target)
    elif isinstance(d, list):
        for item in d[:10]:
            find_keys(item, target)

